const cd=(t,b)=>`<div class="card"><h3>${t}</h3>${b}</div>`;
const ln=(p,t)=>`<a class="x" data-p="${p}">${t}</a>`;


Object.assign(P,{
regras:()=>`<h1>Regras básicas para o mestre</h1><p>Resumo para explicar o jogo aos jogadores. Os links sublinhados abrem as tabelas e informações relacionadas.</p>
${cd('1. O que é o jogo',`<p>Malditos Goblins RPG usa papel, lápis, dados normais (d6) e algumas horas ao redor de uma mesa (ou chat). Cada jogador cria um personagem rolando dados e controla um <b>Goblin</b>: criatura pequena, nojenta, feia, chata, desequilibrada e que morre facilmente. O grupo decide o que fazer dentro da história criada em conjunto; o mestre descreve o mundo e controla os adversários.</p><p><b>Os personagens morrem rápido — muito rápido!</b> Mas em minutos um irmão, filho, tio, sobrinho ou cunhado aparece para se vingar e substituí-lo. Morreu? Role um novo goblin de nível 1 e continue jogando.</p><p>As aventuras típicas são saquear viajantes, sequestrar gente importante, saquear casas humanas, proteger a masmorra e invadir vizinhos (veja ${ln('aventuras','Aventuras e Locais')}).</p>`)}
${cd('2. Criando o goblin (3 etapas)',`<p>Em cada etapa o jogador rola dois dados: o primeiro indica a coluna, o segundo a linha.</p><ul><li><b>Nome:</b> inventado ou rolado na <a class="x" data-t="nome">tabela de nomes</a>. Pode ter um segundo nome de família.</li><li><b>Ocupação e Descritor:</b> role dois dados na <a class="x" data-t="ocup">tabela de ocupação e descritor</a> e anote atributos e equipamento.</li><li><b>Característica:</b> role na <a class="x" data-t="carac">tabela de características</a>; cada uma traz complicações (ou não). “Role 2 vezes” significa ter duas.</li></ul><p>Use a aba ${ln('criar','Criar goblin')} para fazer isso com os dados na tela.</p>`)}
${cd('3. Atributos',`<ul><li><b>Combate:</b> dados rolados para atacar.</li><li><b>Habilidade:</b> dados rolados em ações físicas fora de combate.</li><li><b>Noção:</b> dados rolados para saber se o personagem conhece algo (e para conjurar magias).</li><li><b>Vitalidade:</b> máximo de ferimentos antes de morrer.</li></ul><p>Todo atributo começa com <b>2</b> pontos, modificado pela ocupação (+1 em um atributo) e pelo descritor.</p><ul><li><a class="x" data-o="Mercenário">Mercenário</a> e <a class="x" data-o="Caçador">Caçador</a>: Combate +1 · <a class="x" data-o="Gatuno">Gatuno</a>: Habilidade +1 · <a class="x" data-o="Líder">Líder</a> e <a class="x" data-o="Incendiário">Incendiário</a>: Vitalidade +1 · <a class="x" data-o="Bruxo">Bruxo</a>: Noção +1</li><li>Descritores: Covarde (Combate −1), Atrapalhado (Habilidade −1), Tapado (Noção −1), Fracote (Vitalidade −1), Medíocre (nada), Supimpa (+1 em um atributo à escolha).</li></ul>`)}
${cd('4. Níveis',`<p>Todo goblin começa no nível 1. Sempre que derrotar um oponente, o jogador rola um dado: com “6”, sobe 1 nível e aprende uma nova técnica da ocupação (clique no nome da ocupação acima para ver as técnicas). No nível 4, o goblin fica tão feliz que explode de alegria.</p>`)}
${cd('5. Testes de dados',`<p>Sempre que o resultado de uma ação for incerto, faz-se um <b>Teste</b>: rola-se uma quantidade de dados igual ao atributo testado. Cada dado que cair em <b>4, 5 ou 6</b> é 1 <b>hit</b>.</p><ul><li><b>Teste de Habilidade:</b> algo físico fora de combate. <b>Teste de Noção:</b> saber sobre algum assunto ou coisa específica.</li><li><b>Dificuldade:</b> teste fácil = +1 dado; teste difícil = −1 dado.</li><li><b>Explosão de dado:</b> um “6” além de ser hit permite rolar mais um dado, que também pode explodir, infinitamente.</li><li><b>Explosão de goblin:</b> se todos os dados caírem “1”, o goblin explode em milhões de pedacinhos. Faça outro.</li></ul>${tf(['hits'])}<div class="card"><b>Exemplo:</b> Ploc, o caçador tapado, quer subir pela janela da taverna sem ser notado. Teste de Habilidade 2: rola dois dados e tira “2” e “5”. Só o “5” é hit: entrou, mas por pouco — caiu atrás de um barril e os humanos ouviram o barulho.</div>`)}
${cd('6. Combate',`<ul><li>O combate é dividido em <b>turnos</b>; em seu turno cada jogador dá uma ação ao personagem.</li><li><b>Iniciativa:</b> se os goblins encontram inimigos distraídos, o grupo age primeiro (decidem entre si a ordem). Se esbarram nos inimigos, os inimigos agem primeiro.</li><li><b>Atacar:</b> funciona como um teste, mas usando Combate; cada hit = 1 ferimento no alvo. As <a class="x" data-t="armas">armas</a> acrescentam dados. Explosões valem aqui também.</li><li><b>Esquivar:</b> ao ser atacado, o goblin pode fazer um teste de Combate; cada hit reduz os hits do atacante. Quem se esquiva não ataca no próximo turno.</li><li><b>Bloquear:</b> usando uma <a class="x" data-t="prot">proteção</a> vestida; cada ferimento tomado reduz 1 de Durabilidade dela. Com Durabilidade zero, não bloqueia mais.</li></ul><div class="card"><b>Exemplo:</b> Ploc vê um <a class="x" data-t="inim" data-h="lobo">Lobo</a> distraído e ataca primeiro, arremessando a adaga (+1 dado). Com Combate 3 rola 4 dados: 2, 5, 6, 3 = 2 hits; o 6 explode e dá um 5: 3 hits = 3 ferimentos. O Lobo tem Vitalidade 5 e segue vivo com 3 ferimentos. Agora é o turno do Lobo.</div>`)}
${cd('7. Ferimentos e morte',`<p>Um goblin morre se tiver <b>mais ferimentos que sua Vitalidade</b>. Cada noite de descanso remove 1 ferimento. Morreu: um parente vem se vingar; crie um novo goblin de nível 1.</p>`)}
${cd('8. Magia',`<p>Só o Bruxo conjura. Escolhe 3 magias na criação e as usa livremente. Para conjurar, faz um teste de Noção (4–6 = hit) e consulta a tabela da magia: <b>0 hits</b> costuma ser algo muito ruim, <b>1</b> um efeito fraco, <b>2</b> o efeito esperado, <b>3 ou mais</b> algo exagerado. Magias: ${Object.keys(SP).map(n=>`<a class="x" data-t="sp_${n}">${n}</a>`).join(', ')}.</p>`)}
${cd('9. Equipamento',`<p>Cada ocupação oferece opções de equipamento inicial. Veja <a class="x" data-t="armas">armas</a>, <a class="x" data-t="prot">proteções</a>, <a class="x" data-t="espec">especiais</a> e <a class="x" data-t="equip">equipamentos</a>. Armas com Munição [X] têm limite de X ataques; com Recarga, exigem um turno para recarregar.</p>`)}
${cd('10. Conduzindo a aventura',`<ul><li>Escolha um tipo de aventura (ou role na tabela de aventura aleatória) em ${ln('aventuras','Aventuras e Locais')}; descreva o <a class="x" data-t="local">local</a> e use os <a class="x" data-t="inim">inimigos</a> do livro (adapte o que faltar).</li><li>Para masmorras, use o gerador na aba ${ln('tabelas','Tabelas')}.</li><li>Há ${ln('itens','itens mágicos')} para tesouros e ${ln('manobras','manobras')} que os goblins podem tentar em grupo.</li><li>Goblins quase sempre agem sem plano: improvise consequências divertidas.</li></ul>`)}
${cd('11. Regras opcionais',`<ul><li><b>Voz Goblin:</b> se o jogador imitar a voz de goblin (fina e toda errada) o tempo todo, seu goblin nunca explode ao tirar só “1”. Falar uma palavra sem a voz perde a vantagem até o fim do jogo.</li><li><b>Mas deu ruim…:</b> com 1 hit em Habilidade e sem ideias, role na tabela abaixo.</li><li><b>Níveis épicos:</b> quem chegou ao nível 4 é um mentiroso, mas se os outros acreditarem, pode escolher outra ocupação e ganhar níveis nela.</li><li><b>Jogando sem mestre:</b> use as tabelas para escolher a aventura, gerar cenas (inspiração) e responder perguntas de sim/não.</li></ul>${tf(['ruim','avent','insp','mestre'])}`)}`,
manobras:()=>`<h1>Manobras</h1><div class="hero">${img('p17_95','il')}<p class="f1">Manobras que seu goblin pode realizar no jogo. Muitas exigem um amigo junto. Use o painel de dados abaixo para os testes.</p></div><div class="mg">${[['Catapultando Goblins','Com qualquer pedaço de madeira e uma pedra é possível fazer uma catapulta. Um goblin fica de um lado e o outro pula nela. Aquele que pular deverá testar Habilidade para saber se o outro acertará o alvo proposto. Se falhar neste teste, o goblin catapultado vai se espatifar recebendo 1d6 ferimentos.'],['Pendurar no Inimigo','Goblins são pequenos e podem pular em alvos maiores para atacar pendurados. Para isso, o goblin deve fazer um teste de Habilidade. Se conseguir 1 hit, ele estará em cima da vítima e nos próximos turnos rolará um dado extra em todos os ataques contra este alvo. A vítima não pode atacar um goblin pendurado, mas pode tentar tirar o goblin das suas costas, vencendo num teste de Habilidade.'],['Ataque com Duas Armas','Para atacar com uma arma em cada mão, você deve fazer cada ataque contra alvos diferentes e com 1 dado a menos em ambos os ataques.'],['Cacunda!','Dois goblins podem subir um em cima do outro e lutar como um só. Os dois podem atacar um mesmo alvo, mas não poderão se esquivar. O goblin que estiver em cima pode rolar 1 dado a mais no seu ataque. Todo ferimento sofrido poderá ser dividido entre os dois.'],['Combate Sincronizado','Se três ou mais goblins estiverem atacando o mesmo alvo no mesmo turno, o alvo ficará confuso e rolará 1 dado a menos no seu próximo ataque.'],['Derrubar Inimigo','Contra alvos maiores, um goblin pode ficar atrás do alvo e o outro empurrar. Aquele que for empurrar precisará fazer um teste de Habilidade. Se o goblin conseguir 1 hit apenas, o alvo poderá testar Habilidade e ficar de pé. Se conseguir 2 hits ou mais, o alvo cai para trás e ficará no chão. No chão, ele perderá seu próximo turno para se levantar.'],['Ciranda Mágica','Se seus amigos quiserem ajudar você a conjurar uma magia, eles podem fazer uma ciranda. Pelo menos 2 outros amigos precisam ficar girando e cantando ao seu redor enquanto você conjura a magia. Cada amigo na roda garante 1 dado a mais na sua rolagem.'],['Tralha do Poder','Se um goblin achar um objeto bonito e fizer pelo menos dez outros goblins concordarem que é bonito, este objeto se torna uma “Tralha do Poder”. Você ganha um goblin seguidor que fará tudo que você quiser. Ele só vai embora se você perder a tralha, ou se ele conseguir roubar a sua tralha (e ele vai tentar).']].map(m=>`<div class="card"><b class="ti">${m[0]}</b><p>${lk(m[1])}</p></div>`).join('')}</div>`,
aventuras:()=>`<h1>Aventuras e Locais</h1><div class="hero">${img('p18_101')}<p class="f1">Os cinco tipos de aventuras mais comuns para goblins, e descrições de locais para o mestre preguiçoso.</p></div>
${cd('Saquear Viajante',`<p>O tipo de aventura mais comum, já que os goblins não precisam fazer nada: o bando fica parado na beira da estrada esperando alguém passar. Role dois dados, some e confira quem apareceu.</p>${tbl('viajante')}<p>O bando pode pedir os pertences do viajante ou simplesmente atacar. Se optar por negociar, veja primeiro se o viajante tem mais Combate que o goblin mais forte do grupo: se sim, ele não negocia e ataca primeiro o bando. Se não, pode rolar uma negociação.</p><p>Na negociação, um goblin do bando é o negociador e faz um teste de Noção; a vítima faz o mesmo. Se o bando tiver mais hits, a vítima entrega tudo. Se empatar, a negociação continua. Se a vítima tiver mais hits, os goblins ficam confusos e entregam todos os seus pertences à vítima, que sai dali feliz e com vida.</p>`)}
${cd('Sequestrar Pessoa Importante',`<p>Pegar alguém importante e pedir dinheiro em troca parece interessante para os goblins; o problema é que eles não são tão espertos assim para fazer isso dar certo. O grupo pode escolher um alvo, mas possivelmente a escolha será aleatória:</p>${tbl('vitima')}<p>Depois de escolher, eles têm que procurar a vítima. Se algum goblin conseguir 2 hits em um teste de Noção, saberá aonde ir; se não, vão para um lugar aleatório (veja Saquear Casa Humana). O pedido de resgate pode ser qualquer coisa:</p>${tbl('recomp')}`)}
${cd('Saquear Casa Humana',`<p>Goblins não planejam tanto: vão andando em direção a uma cidade até encontrar a primeira casa para roubar. Nem sempre é uma casa, pode ser uma série de coisas. Role um dado e veja o que o bando encontrou (clique no local para ver detalhes):</p>${tbl('local')}`)}
${cd('Proteger Masmorra',`<p>Alguém está entrando no lar dos goblins. O bando deverá estar preparado para enfrentar qualquer coisa:</p>${tbl('invas')}`)}
${cd('Invadir Vizinhos',`<p>Talvez a rixa com os vizinhos tenha chegado a um ponto que não dá para esperar mais. O negócio agora é resolver na mão isso! Chegando lá, o bando vai encontrar:</p>${tbl('viz')}<p><b>Bando Rival:</b> um grupo de goblins exatamente igual ao grupo dos jogadores, porém com algumas características diferentes. Para cada goblin, role na tabela abaixo.</p>${tbl('rival')}`)}
<h2>Locais para explorar</h2><p>Descrição de alguns locais para você que é mestre preguiçoso.</p><div class="mg">${Object.keys(LOC).map(n=>`<div class="card"><b class="ti">${n}</b><p>${lk(LOC[n])}</p></div>`).join('')}</div>`,
itens:()=>`<h1>Itens Mágicos</h1><div class="hero">${img('p24_130')}<p class="f1">Um item mágico é uma raridade e alguns goblins só colecionam porque são bonitos e brilhantes. Quando encontrar um, role um dado para saber o tipo e depois na tabela correspondente. <b>Artefato:</b> item único e muito poderoso. <b>Especial:</b> feito por feiticeiros e elfos, poderoso em quaisquer mãos. <b>Estranho:</b> tem magia, mas não necessariamente é bom (ou é bom só para goblins). <b>Porcaria:</b> são apenas porcarias, mas quem disse que goblins não vão gostar?</p></div>${tf(['tipo','artef','especial','estranho','porcaria','pocao','anel'])}<h2>Lista de Itens Mágicos</h2><div class="mg">${Object.keys(IT).map(itemCard).join('')}</div>`,
adapt:()=>`<h1>Adaptações</h1><p>Regras para jogar outros tipos de campanha usando o sistema de goblins.</p>
<details open><summary class="big">Chamado de Cthulin</summary>${img('p32_4')}<p>Muito horror (e fedor) cósmico. Ideal para uma aventura de investigação sobrenatural em um cenário onde os goblins estão no lugar dos humanos.</p><h3>Personagens</h3><p>Crie seus personagens normalmente, mas cada ocupação tem outro nome e todos começam com um Chapéu ou um Livro Especial.</p>${tbl('c_oc')}<h3>Investigação</h3><p>O mestre precisa inventar o caso, criando cenas e escolhendo um horror. Para cada cena, cria as pistas. Os jogadores tentam achá-las apenas dizendo o que seu personagem faz. Se, por exemplo, a arma do crime está na gaveta da escrivaninha, o mestre diz que os personagens só veem uma escrivaninha; se o jogador disser que abre as gavetas, aí sim o mestre diz o que foi encontrado.</p><p>Se os jogadores não acharem as pistas, podem fazer um teste de Noção. Com 1 hit, o mestre dá uma dica bem mais aberta. Com 2 hits, diz que o personagem pensa onde procurar. Com 3 hits, explica onde está, mas algo sobrenatural acontece na cena.</p><h3>Eventos sobrenaturais</h3><p>Sempre que algum personagem consegue 3 hits em qualquer teste, role um dado:</p>${tbl('c_ev')}<h3>Medo</h3><p>Todos os personagens podem receber Medo. Se receber mais Medo que seus pontos de Noção, você perde seu personagem para a loucura. Pode eliminar todo o Medo se queimar um livro especial ou achar um lugar sagrado para descansar.</p><h3>Livros especiais</h3>${img('p33_9')}<p>Livros que contêm magias: qualquer magia do Bruxo ou a magia abaixo. Alguns Horrores são mais difíceis de invocar: Shogoth e Crias reduzem 1 dado; Cthulhu e Azathoth reduzem 2 dados da rolagem.</p>${tbl('c_inv')}<h3>Horrores</h3>${tbl('c_hor')}</details>
<details><summary class="big">PokéPragas</summary>${img('p35_18')}<p>Imagine que você é um goblin treinador de ratos para uma rinha de bichos mágicos. Na criação, você não rola a ocupação: começa como <b>Treinador</b>.</p><div class="card"><b class="ti">Treinador</b> <small>(Habilidade +1)</small><br><b>Equipamento:</b> 6 PokéPedras<div class="tec"><b>Nível 1 — PokéPraga Inicial:</b> você começa com uma PokéPraga incomum.</div><div class="tec"><b>Nível 2 — Mestre da Evolução:</b> sua PokéPraga evolui mais fácil: role dois dados na hora de verificar.</div><div class="tec"><b>Nível 3 — Mestre Treinador:</b> você se tornou o melhor dos melhores. Pode rir dos outros agora.</div></div><h3>PokéPedras</h3><p>Objetos mágicos raros. Você começa com 6 e pode achar mais em tesouros e masmorras, ou roubar de outro treinador (é o jeito mais fácil). Goblins de outras ocupações também podem ter PokéPragas se acharem (ou roubarem) PokéPedras.</p><h3>PokéPragas</h3><p>Animais pequenos e nojentos que nasceram com o poder de um elemento: Comuns, Incomuns e Raras. Para gerar uma, role um dado na tabela Bicho (conforme a raridade) e dois dados na tabela Elemento (um na linha, outro na coluna).</p>${tbl('p_bicho')}${tbl('p_elem')}<h3>Evolução</h3><p>Toda PokéPraga que ganha uma PokéBatalha rola um dado; com 6, evolui: ganha Vitalidade +1 e um novo elemento (role na tabela acima). Some os bônus de atributo do elemento, mas ignore a fraqueza.</p><h3>Encontrando e capturando</h3><p>Passe o dia inteiro andando de um lado para outro na grama alta e role:</p>${tbl('p_proc')}<p>Para capturar, arremesse uma PokéPedra e faça um teste de Habilidade: comuns precisam de 1 hit, incomuns de 2 e raras de 3. Ao capturar, dê um nome à criatura: ela vira energia e é absorvida pela PokéPedra. Depois você arremessa a pedra no chão e fala o nome para que ela saia e lute por você.</p><h3>Ficha das pragas</h3><p>A ficha é a combinação do bicho e do elemento. Os ataques normais usam Combate e não têm elemento. Para um ataque elemental, faça um ataque usando Habilidade; se causar dano e for da fraqueza do oponente, causa +1 ferimento. Em combate, quem tiver mais Noção começa atacando. Se uma PokéPraga tiver mais ferimentos que Vitalidade, desmaia e volta para a PokéPedra.</p>${tbl('p_bst')}${tbl('p_els')}</details>
<details><summary class="big">WarGoblin 40k</summary><p>Cenário futurista distópico onde tudo é guerra. Qualquer semelhança com uma franquia inglesa de wargame é pura safadeza do autor.</p><h3>História</h3><p>Este é o 40º milênio. Os goblins deixaram seu planeta natal e se espalharam pela galáxia, mas nada disso aconteceu tão rápido. Há um tempinho, um goblin disse que seria o imperador da coisa toda e todo mundo aceitou porque ele tinha uma armadura dourada maneira. Gostava de ser chamado apenas de “Imperador”, assim ninguém precisava decorar o nome dele. Para organizar as paradas, botou os 13 primos para comandar exércitos de goblins em vários planetas.</p><p>Um dia, o primo Honório achou que ter uma armadura bonita não era motivo para virar imperador e decidiu traí-lo. Veio uma guerra civil, os primos se dividiram em turminhas: “A Treta do Honório”. Hoje todo mundo está em guerra, e ainda há a galera alienígena: os Insetões, os Robôs e os Zelfos.</p><h3>Ocupações</h3><p>Cada ocupação é uma turminha. Todos começam com dois equipamentos à escolha: Armadura Espacial (recomendado), Pistola Bólter, Metranca de Plasma, Lança-chamas, Espada Serra ou Mãozona do Poder.</p>${tbl('w_oc')}${tbl('w_arm')}${tbl('w_prot')}<h3>Outros alienígenas</h3><p><b>Insetões:</b> insetos gigantes que gostam de invadir planetas e deixar tudo nojento; adoram devorar goblins e destruir civilizações. <b>Robôs:</b> um exército que ninguém sabe de onde veio; talvez do futuro. <b>Zelfos:</b> pálidos humanoides que eram inteligentes até colocarem capacetes em formato de ovo e nunca mais conseguirem tirar; não conseguiram mais achar seu planeta.</p>${tbl('w_alien')}</details>
<details><summary class="big">Goblin High</summary><div class="hero">${img('p39_34')}${img('p39_36')}</div><p>É na escola que aprendemos a fazer amigos. “Goblin High” é uma escola para goblins: você é um aluno e interage com seus colegas de classe. Gere aleatoriamente todos os goblins da turma.</p><h3>Reações</h3><p>Cada estudante tem uma reação com o seu personagem. Quando não souber, role um dado. Presentes ou ajuda aumentam a Reação nessa escala (acima de Amigável, vira seu Amigo). Erros ou algo de que ele não goste a reduzem (abaixo de Hostil, vira seu Inimigo).</p>${tbl('g_reac')}<h3>Conversar</h3><p>Você pode conversar com qualquer estudante Neutro ou Amigável. Se tentar com um Hostil, ele te agride (apenas um ataque) e vai embora. Faça um teste de Noção: se falhar, desça um nível a Reação (exceto se for Amigo); com pelo menos 1 hit, role na tabela:</p>${tbl('g_conv')}<h3>Agradar</h3><p>Se fizer algo que sabe que o estudante gosta, aumente a Reação em um nível. Também pode tentar falar algo agradável: teste de Noção; se falhar, reduz a Reação (mesmo se for Amigo); com pelo menos 2 hits, aumenta em um nível. É preciso conversar antes e não dá para agradar alguém duas vezes no mesmo dia.</p>${tbl('g_tab')}<h3>Estudantes</h3><p>Faça uma lista dos goblins da turma. Sempre que precisar definir um Estudante, role nessa lista.</p><h3>Amigos e Romance</h3><p>Se alguém virou seu Amigo, você pode conversar sobre o Segredo dele e ele o revelará. Amigos ajudam sempre que precisar (lutam com você). Se descobriu o segredo e caiu “6” (ele gosta de você), pode começar o Romance. Outra forma: descobrir Assunto Favorito, Gostos e Segredo e vencer um teste de Noção; o número de hits é o tempo em meses que ficarão juntos.</p><h3>Inimigos</h3><p>Para desfazer uma inimizade, consiga 3 hits ao tentar agradar em dois dias seguidos: o estudante segue Hostil, mas não inimigo. Um inimigo está sempre à espera para te pegar: todo final de dia, role:</p>${tbl('g_saida')}<p>Se começar uma Briga, ele junta 1d6-1 amigos contra você; seus amigos lutam do seu lado e algum romance fica com Combate +1 até o final da luta. Vencer dá status e popularidade; perder te humilha e todos (exceto Amigos) reduzem a Reação com você.</p></details>
<details><summary class="big">Vale dos Goblins</summary>${img('p40_42')}<p>Existe um lugar onde os goblins podem descansar e explodir em paz: uma fazendinha para passar os dias pescando, cozinhando e plantando batatas.</p><div class="card"><b class="ti">Fazendeiro</b> <small>(Habilidade ou Noção +1)</small><br><b>Equipamento (escolha):</b> Bacamarte, Chapéu e Enxada — ou — Picareta, Machado, Enxada e Vara de Pesca.<div class="tec"><b>Nível 1 — Herança:</b> você herdou uma fazenda com 1 galinha e 1 vaca.</div><div class="tec"><b>Nível 2 — Dedo Verde:</b> sempre que colher uma horta, recebe o dobro de alimentos.</div><div class="tec"><b>Nível 3 — Matador de Pragas:</b> rola 1 dado a mais em combate contra criaturas consideradas pestes nas fazendas.</div></div><h3>Fazenda</h3><p>Façam o mapa do vale como quiserem: o ideal é ter um rio, um lago, montanhas, alguns bosques e uma fazenda. Dá para usar estas regras em qualquer cenário. Na fazenda pode haver galinhas, vacas e hortas. Se o grupo achar ou herdar uma fazenda, o jogo pode começar!</p><h3>Coleta</h3><p>Todo dia (no jogo, ou dia de verdade para uma experiência mais longa) dá para coletar recursos. <b>Ovos e Leite:</b> para cada galinha e vaca, teste de Habilidade; cada hit = 1 ovo ou 1 litro de leite. <b>Horta:</b> para cada metro quadrado, teste de Noção; cada hit = 1 do produto plantado. <b>Pedras:</b> precisa de Picareta; para cada mina na montanha, teste de Combate; cada hit = 1 bloco de pedra. <b>Madeira:</b> precisa de Machado; para cada bosque, teste de Combate; cada hit = 1 tábua.</p><h3>Horta</h3><p>Com uma Enxada, você ara a terra e planta algo uma vez ao dia: teste de Habilidade; cada hit = 1 metro quadrado plantado. Só dá para colher em 1d6 dias; depois de colher, é preciso plantar de novo. Alimentos: Cenoura, Batata, Alface, Brócolis, Morango, Banana, Arroz, Trigo e Milho.</p><h3>Pescaria</h3><p>Em lagos ou rios, com uma Vara de Pesca. É basicamente Yahtzee/General/Yam: jogue 5 dados e tente combinações (par, trio, quadra e general). Pode rerrolar de 1 a 5 dados que não gostou, só duas vezes. Sem combinação, não pegou nada. O valor do dado indica o tipo de peixe; a combinação, o peso.</p>${tbl('v_peixe')}${tbl('v_peso')}<h3>Construções</h3><p>Fabrique ferramentas e construa fazendas juntando os recursos e conseguindo 2 hits em um teste de Noção.</p>${tbl('v_cons')}<h3>Cozinha</h3><p>Para fazer um prato é preciso ter os ingredientes e fazer um teste de Noção com a quantidade de hits exigida. Se não conseguir, gastou todos os ingredientes à toa.</p>${tbl('v_coz')}<h3>Vilarejo</h3><p>Você pode criar um vilarejo de goblins no vale. Use as regras da adaptação Goblin High e crie goblins para interagir, trocando os assuntos de escola por assuntos de fazenda.</p></details>`});

function go(p){if(!P[p])p='inicio';const m=$('#main');m.innerHTML=P[p]();document.querySelectorAll('nav [data-p]').forEach(b=>b.classList.toggle('on',b.dataset.p==p));if(p=='fichas')fl();if(p=='criar'){C={nome:'',sob:'',oc:'',ds:'',ca:'',sup:'Combate',eq:''};prev()}window.scrollTo(0,0)}
function modal(h){$('#mc').innerHTML=h;$('#md').style.display='flex'}
function hlm(h){if(!h)return;let f;$('#mc').querySelectorAll('tr[data-key],tr:not([data-key])').forEach(r=>{if(r.rowIndex>0&&r.textContent.toLowerCase().includes(h)){r.classList.add('hl');f=f||r}});f&&f.scrollIntoView({block:'center'})}
/* eventos */
document.addEventListener('click',async e=>{const b=e.target.closest('[data-p],[data-t],[data-o],[data-i],[data-act],[data-a],[data-d],[data-n],#dm,#dt,#dh1,#dp,#mx,#md,#ca,#cs2,#tgo');if(!b)return;
if(b.id=='md'&&e.target!=b)return;if(b.id=='md'||b.id=='mx'){$('#md').style.display='none';return}
if(b.dataset.p){$('#md').style.display='none';location.hash=b.dataset.p;return}
if(b.dataset.t){modal(`<h2>${TB[b.dataset.t].t}</h2>`+tbl(b.dataset.t,1));hlm(b.dataset.h);return}
if(b.dataset.i){const t=b.dataset.i[0],n=b.dataset.i.slice(2);modal(t=='m'?itemCard(n)+(n=='Anel Mágico'?tbl('anel',1):n=='Poção'?tbl('pocao',1):''):`<h2>${E(n)}</h2><p>${t=='l'?lk(LOC[n]):E(t=='c'?CD[n]:DSC[n])}</p>`);return}
if(b.dataset.o){modal(occ(b.dataset.o));return}
if(b.id=='dm'){dock.classList.remove('o');$('#dd').innerHTML='';$('#dr').innerHTML='';$('#dl').textContent='Role os dados!';return}
if(b.id=='dt'){dock.classList.toggle('o');return}
if(b.dataset.d){const i=$('#dn');i.value=Math.max(0,+i.value+ +b.dataset.d);return}
if(b.id=='dh1'){roll(+$('#dn').value,'Teste');return}
if(b.id=='dp'){const{v,sum}=await rp(+$('#dn').value,'d6 simples');$('#dr').innerHTML=`<b class="big">Total ${sum}</b> (${v.join(' + ')})`;return}
if(b.dataset.n){const{v,sum}=await rp(+b.dataset.n,b.dataset.n+'d6');$('#dr').innerHTML=`<b class="big">Total ${sum}</b> (${v.join(' + ')})`;return}
if(b.id=='tgo'){roll(+$('#tn').value+ +$('#tdf').value,'Teste');return}
const a=b.dataset.act,tb=b.closest('.tb');
if(a=='tr'){const t=TB[tb.dataset.k],{v,sum}=await rp(t.d,t.t),o=tb.querySelector('.off'),tot=sum+(o?+o.value:0),r=hlr(tb,tot);$('#dr').innerHTML=`<b class="big">${tot}</b> — ${r?[...r.cells].slice(1).map(c=>c.textContent).join(' — '):''}`;return}
if(a=='tg'){const{v}=await rp(2,TB[tb.dataset.k].t.split(' —')[0]),t=TB[tb.dataset.k].r[v[1]-1][v[0]-1];hlc(tb.dataset.k,v[0],v[1],tb.parentNode);$('#dr').innerHTML=`<b class="big">${t}</b>`;return}
if(a=='th'){const n=+tb.querySelector('.hn').value,h=await roll(n,TB[tb.dataset.k].t.split(' —')[0]);hlr(tb,Math.min(h,3)+(h>=3?0:0));return}
if(a=='rn')return rName();if(a=='rn2')return rName(1);if(a=='ro')return rOc();if(a=='rc')return rCa();
if(a=='blank'){S.unshift({id:Date.now(),nome:'Goblin',nivel:1,oc:'',ds:'',ca:'',sup:'Combate',eq:'',arma:'',fer:0,ex:0});sv();fl();return}
if(b.id=='ca'){await rName();await rOc();await rCa();return}
if(b.id=='cs2'){if(!C.oc||!C.ds){od();$('#dl').textContent='Escolha ocupação e descritor antes de salvar.';return}S.unshift({id:Date.now(),nome:((C.nome||'Goblin')+' '+(C.sob||'')).trim(),nivel:1,oc:C.oc,ds:C.ds,ca:C.ca,sup:C.sup,eq:C.eq,arma:'',fer:0,ex:0});sv();location.hash='fichas';return}
if(b.dataset.a=='pr2'){try{window.print()}catch(e){}return}
if(b.dataset.a){const c=b.closest('.card[data-id]'),s=S.find(x=>x.id==c.dataset.id),a=atr(s),ex=+s.ex||0,w=W.find(x=>x[0]==s.arma),bn=w?parseInt(w[3]):0,x=b.dataset.a,n=s.nome;
if(x=='at')return roll(a[b.dataset.at]+ex,n+' — '+b.dataset.at);
if(x=='atk')return roll(a.Combate+bn+ex,n+' ataca'+(w?' com '+w[0]:''),h=>`→ ${h} ferimento${h==1?'':'s'} no alvo`);
if(x=='esq')return roll(a.Combate+ex,n+' esquiva',h=>`→ reduz ${h} hit(s) do atacante`);
if(x=='cast'){const m=s.mg||'Fogo';return roll(a['Noção']+ex,n+' conjura '+m,h=>'→ '+SP[m][Math.min(h,3)])}
if(x=='fer'){s.fer=Math.max(0,s.fer+ +b.dataset.v);sv();fl();return}
if(x=='win'){const{v}=await rp(1,n+' derrotou um inimigo');if(v[0]==6&&s.nivel<4){s.nivel++;sv();fl();$('#dr').innerHTML='<b class="big">6! Subiu de nível.</b>'}else $('#dr').innerHTML='Nada de nível desta vez.';return}
if(x=='del'){if(b.dataset.cf!='1'){b.dataset.cf='1';b.textContent='Clique de novo para excluir';setTimeout(()=>{b.dataset.cf='';b.textContent='Excluir'},3500);return}S=S.filter(y=>y!=s);sv();fl();return}
if(x=='print'){modal(pcard(s)+'<p class="noprint"><button class="b" data-a="pr2">🖨 Imprimir</button> <small>Se a janela de impressão não abrir, use Ctrl+P (⌘+P no Mac).</small></p>');return}}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.c){C[t.dataset.c]=t.value;if(t.dataset.c=='oc'){C.eq=''}prev();return}
const f=t.dataset.f,c=t.closest('.card[data-id]');if(f&&c){const s=S.find(x=>x.id==c.dataset.id);s[f]=t.type=='number'?+t.value:t.value;if(f=='nivel')s.nivel=Math.min(4,Math.max(1,s.nivel||1));sv();fl()}});
addEventListener('hashchange',()=>go(location.hash.slice(1)));go(location.hash.slice(1)||'inicio');
